spec.expr:
sum(
  rate(
    http_server_requests_seconds_count{
      job="api-gateway",
      status=~"5.."
    }[5m]
  )
)
/
sum(
  rate(
    http_server_requests_seconds_count{
      job="api-gateway"
    }[5m]
  )
)
* 100

(
  1 -
  (
    (
      sum(
        rate(
          http_server_requests_seconds_count{
            job="api-gateway",
            status=~"5.."
          }[5m]
        )
      )
      or vector(0)
    )
    /
    sum(
      rate(
        http_server_requests_seconds_count{
          job="api-gateway"
        }[5m]
      )
    )
  )
) * 100

100 *
sum by (job) (
  rate(http_server_requests_seconds_count{
    status=~"4..|5..",
    uri!~"/actuator.*"
  }[1m])
)
/
sum by (job) (
  rate(http_server_requests_seconds_count{
    uri!~"/actuator.*"
  }[1m])
)

1000 *
sum by (job) (
  rate(http_server_requests_seconds_sum{
    uri!~"/actuator.*"
  }[1m])
)
/
sum by (job) (
  rate(http_server_requests_seconds_count{
    uri!~"/actuator.*"
  }[1m])
)

100 *
sum by (job) (
  jvm_memory_used_bytes{area="heap"}
)
/
sum by (job) (
  jvm_memory_max_bytes{area="heap"} > 0
)
